create table minor_attribute_definitions (id varchar(36) primary key, campaign_id varchar(36) not null, attr_key varchar(120) not null, name varchar(160) not null, max_formula varchar(500) not null, bonus_source varchar(120), attribute_type varchar(20) not null, created_at timestamp not null, constraint fk_minor_attr_campaign foreign key(campaign_id) references campaigns(id), constraint uq_minor_attr_campaign_key unique(campaign_id, attr_key));
create table character_minor_attribute_values (id varchar(36) primary key, character_id varchar(36) not null, definition_id varchar(36) not null, attribute_value int not null, constraint fk_minor_value_character foreign key(character_id) references characters(id), constraint fk_minor_value_definition foreign key(definition_id) references minor_attribute_definitions(id), constraint uq_minor_value unique(character_id, definition_id));
create index ix_minor_attr_campaign on minor_attribute_definitions(campaign_id);
